<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { getApiBaseUrl } from '@/config/api'

type Order = { reference: string; status: 'awaiting_transfer' | 'pending_payphone' | 'paid' | 'cancelled'; paymentMethod: 'payphone' | 'transfer'; totalCents: number; createdAt: string; hasTransferReceipt: boolean; buyer: { firstName: string; lastName: string; email: string; phone: string }; delivery: { city: string; province: string; address: string } }
const router = useRouter()
const apiBaseUrl = getApiBaseUrl()
const orders = ref<Order[]>([])
const section = ref<'all' | 'transfer' | 'incomplete' | 'automatic'>('all')
const toast = ref('')
const isLoading = ref(true)
const money = (cents: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100)
const visibleOrders = computed(() => orders.value.filter((order) => section.value === 'all' || (section.value === 'transfer' && order.paymentMethod === 'transfer' && order.status === 'awaiting_transfer') || (section.value === 'incomplete' && (order.status === 'pending_payphone' || order.status === 'cancelled')) || (section.value === 'automatic' && order.paymentMethod === 'payphone' && order.status === 'paid')))
const counts = computed(() => ({ transfer: orders.value.filter((o) => o.paymentMethod === 'transfer' && o.status === 'awaiting_transfer').length, incomplete: orders.value.filter((o) => o.status === 'pending_payphone' || o.status === 'cancelled').length, automatic: orders.value.filter((o) => o.paymentMethod === 'payphone' && o.status === 'paid').length }))
function headers() { return { Authorization: `Bearer ${localStorage.getItem('access_token') || ''}`, 'Content-Type': 'application/json' } }
function notify(message: string) { toast.value = message; window.setTimeout(() => { toast.value = '' }, 3200) }
async function loadOrders() { isLoading.value = true; try { const response = await fetch(`${apiBaseUrl}/orders/admin/list`, { headers: headers() }); const data = await response.json() as { orders?: Order[]; message?: string }; if (!response.ok) throw new Error(data.message || 'No pudimos cargar las compras.'); orders.value = data.orders || [] } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos cargar las compras.') } finally { isLoading.value = false } }
async function changeStatus(order: Order, status: 'paid' | 'cancelled') { try { const response = await fetch(`${apiBaseUrl}/orders/admin/${encodeURIComponent(order.reference)}/status`, { method: 'PATCH', headers: headers(), body: JSON.stringify({ status }) }); const data = await response.json() as { message?: string }; if (!response.ok) throw new Error(data.message || 'No pudimos actualizar el pedido.'); order.status = status; notify(status === 'paid' ? 'Pedido marcado como pagado.' : 'Pedido marcado como no concretado.') } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos actualizar el pedido.') } }
async function seeReceipt(order: Order) { try { const response = await fetch(`${apiBaseUrl}/orders/admin/${encodeURIComponent(order.reference)}/receipt`, { headers: headers() }); const data = await response.json() as { url?: string; message?: string }; if (!response.ok || !data.url) throw new Error(data.message || 'No encontramos el comprobante.'); window.open(data.url, '_blank', 'noopener,noreferrer') } catch (error) { notify(error instanceof Error ? error.message : 'No pudimos abrir el comprobante.') } }
function logout() { localStorage.removeItem('access_token'); localStorage.removeItem('user_id'); void router.replace('/login') }
onMounted(loadOrders)
</script>

<template>
  <main class="admin"><aside><a class="brand" href="/">OMG <span>LASHES</span></a><p>OPERACION</p><button :class="{ active: section === 'all' }" @click="section = 'all'">Todas las compras</button><button :class="{ active: section === 'transfer' }" @click="section = 'transfer'">Transferencias <b>{{ counts.transfer }}</b></button><button :class="{ active: section === 'incomplete' }" @click="section = 'incomplete'">No concretadas <b>{{ counts.incomplete }}</b></button><button :class="{ active: section === 'automatic' }" @click="section = 'automatic'">Pagos automaticos <b>{{ counts.automatic }}</b></button><button class="logout" @click="logout">Cerrar sesion</button></aside><section class="content"><header><div><p>ADMINISTRACION</p><h1>Compras <em>OMG.</em></h1></div><button @click="loadOrders">Actualizar</button></header><div class="summary"><span><b>{{ orders.length }}</b> pedidos</span><span><b>{{ counts.transfer }}</b> por verificar</span><span><b>{{ counts.automatic }}</b> pagados automaticamente</span></div><p v-if="isLoading" class="empty">Cargando compras...</p><p v-else-if="!visibleOrders.length" class="empty">No hay compras en esta seccion.</p><div v-else class="orders"><article v-for="order in visibleOrders" :key="order.reference"><div class="order-head"><div><small>{{ new Date(order.createdAt).toLocaleString('es-EC') }}</small><h2>{{ order.reference }}</h2></div><strong :class="order.status">{{ order.status === 'paid' ? 'PAGADO' : order.status === 'awaiting_transfer' ? 'PENDIENTE DE TRANSFERENCIA' : order.status === 'pending_payphone' ? 'PAGO NO CONCRETADO' : 'CANCELADO' }}</strong></div><div class="order-grid"><p><b>Contacto</b>{{ order.buyer.firstName }} {{ order.buyer.lastName }}<a :href="`mailto:${order.buyer.email}`">{{ order.buyer.email }}</a><a :href="`tel:${order.buyer.phone}`">{{ order.buyer.phone }}</a></p><p><b>Entrega</b>{{ order.delivery.address }}<span>{{ order.delivery.city }}, {{ order.delivery.province }}</span></p><p><b>Pago</b>{{ order.paymentMethod === 'payphone' ? 'PayPhone' : 'Transferencia' }}<span>Total {{ money(order.totalCents) }}</span></p></div><footer v-if="order.status === 'awaiting_transfer'"><button v-if="order.hasTransferReceipt" @click="seeReceipt(order)">Ver comprobante</button><span v-else>Sin comprobante aun</span><button class="paid-action" @click="changeStatus(order, 'paid')">Marcar pagado</button><button class="cancel-action" @click="changeStatus(order, 'cancelled')">No se concreto</button></footer></article></div></section><Transition name="toast"><p v-if="toast" class="toast" role="status">{{ toast }}</p></Transition></main>
</template>

<style scoped lang="scss">
.admin { --ink:#211e1d;--cream:#fbf7f2;--pink:#f4d9d5;--copper:#b86f54;background:var(--cream);color:var(--ink);display:grid;font-family:Arial,sans-serif;grid-template-columns:245px 1fr;min-height:100vh }.admin aside { background:var(--ink);color:var(--cream);display:flex;flex-direction:column;gap:8px;padding:30px 20px }.brand { color:inherit;font:20px Georgia,serif;letter-spacing:-.1em;margin-bottom:48px;text-decoration:none }.brand span { font-size:15px }.admin aside p,.content header p { color:#c99584;font-size:10px;letter-spacing:.12em;margin:0 0 9px }.admin aside button { background:transparent;border:0;color:inherit;cursor:pointer;display:flex;font-size:12px;justify-content:space-between;padding:13px;text-align:left }.admin aside button.active { background:var(--copper) }.admin aside b { background:rgba(255,255,255,.16);border-radius:20px;padding:2px 7px }.admin .logout { margin-top:auto }.content { padding:48px;max-width:1350px;width:100% }.content header { align-items:end;display:flex;justify-content:space-between }.content h1 { font:600 52px/.9 Georgia,serif;letter-spacing:-.07em;margin:0 }.content h1 em { color:var(--copper);font-weight:normal }.content header button,.orders footer button { background:var(--ink);border:0;color:var(--cream);cursor:pointer;font-size:11px;padding:12px 16px }.summary { display:flex;gap:14px;margin:35px 0 25px }.summary span { background:var(--pink);font-size:12px;padding:13px }.summary b { font-size:17px }.orders { display:grid;gap:15px }.orders article { background:#fffdfa;border:1px solid #e0d5d0;padding:22px }.order-head { align-items:start;border-bottom:1px solid #eaded8;display:flex;justify-content:space-between;padding-bottom:16px }.order-head small { color:#756d69;font-size:10px }.order-head h2 { font:600 18px Georgia,serif;margin:6px 0 0 }.order-head strong { font-size:10px;letter-spacing:.06em;padding:7px 9px }.order-head strong.paid { background:#d9ecdd;color:#216335 }.order-head strong.awaiting_transfer { background:#f7e4bc;color:#7b5110 }.order-head strong.pending_payphone,.order-head strong.cancelled { background:#f5d8d8;color:#9b3030 }.order-grid { display:grid;gap:24px;grid-template-columns:1.3fr 1fr 1fr;padding:18px 0 }.order-grid p { display:grid;font-size:13px;gap:5px;line-height:1.35;margin:0 }.order-grid b { color:var(--copper);font-size:10px;letter-spacing:.07em;text-transform:uppercase }.order-grid a { color:inherit }.order-grid span { color:#756d69 }.orders footer { align-items:center;border-top:1px solid #eaded8;display:flex;gap:9px;padding-top:15px }.orders footer span { color:#756d69;font-size:11px;margin-right:auto }.orders footer button:first-child { margin-right:auto }.orders footer .paid-action { background:#216335 }.orders footer .cancel-action { background:transparent;border:1px solid #9b3030;color:#9b3030 }.empty { color:#756d69;margin-top:55px }.toast { background:var(--ink);bottom:24px;color:var(--cream);font-size:12px;left:50%;padding:14px 18px;position:fixed;transform:translateX(-50%);z-index:5 }@media (max-width:760px) { .admin { display:block }.admin aside { gap:4px;padding:20px }.brand { margin-bottom:15px }.admin aside button { display:none }.admin aside .logout { display:block;margin:4px 0 0;padding-left:0 }.content { padding:30px 18px }.content h1 { font-size:42px }.summary { flex-wrap:wrap }.order-grid { grid-template-columns:1fr;gap:15px }.orders footer { align-items:stretch;flex-wrap:wrap }.orders footer button:first-child { margin-right:0 }.orders footer span { margin-right:0;width:100% } }
</style>
